    for r1 in range(H):
        # For each possible left column
        for c1 in range(W):
            val = grid[r1][c1]
            if val == 0:
                continue

            # Find right extent of top border
            c_end = c1
            while c_end + 1 < W and grid[r1][c_end+1] == val:
                c_end += 1

            if c_end == c1:
